import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"UnrealZoo: Enriching Photo-realistic Virtual Worlds for Embodied AI","description":"","frontmatter":{"title":"UnrealZoo: Enriching Photo-realistic Virtual Worlds for Embodied AI","arxiv":"2412.20977","date":"2024-12-30","authors":"Fangwei Zhong, Kui Wu, Churan Wang, Hao Chen, Hai Ci, Zhoujun Li, Yizhou Wang","categories":"cs.AI, cs.CV, cs.RO","topics":"具身智能, 开放世界仿真, 视觉导航与跟踪","outline":[2,2]},"headers":[],"relativePath":"papers/2412.20977.md","filePath":"papers/2412.20977.md","lastUpdated":null}'),l={name:"papers/2412.20977.md"};function e(m,s,i,r,c,o){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="unrealzoo-enriching-photo-realistic-virtual-worlds-for-embodied-ai" tabindex="-1">UnrealZoo: Enriching Photo-realistic Virtual Worlds for Embodied AI <a class="header-anchor" href="#unrealzoo-enriching-photo-realistic-virtual-worlds-for-embodied-ai" aria-label="Permalink to &quot;UnrealZoo: Enriching Photo-realistic Virtual Worlds for Embodied AI&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2412.20977" target="_blank" rel="noreferrer">2412.20977</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-12-30</td></tr><tr><td><strong>作者</strong></td><td>Fangwei Zhong, Kui Wu, Churan Wang, Hao Chen, Hai Ci, Zhoujun Li, Yizhou Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CV, cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用 100 个虚幻引擎实景场景加 67 种可控形态，配上把 FPS 提升数倍的 UnrealCV+，把&quot;非结构地形、形态迁移、控制延迟&quot;这三个被室内仿真器掩盖的开放世界难题暴露出来。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>具身智能体目前基本是&quot;宅男&quot;——被关在受控的室内环境里，很少走出去面对开放世界。AI2-THOR、Habitat、VirtualHome 专注家居日常，CARLA、AirSim 专注城市道路。这种窄化的场景分布让智能体在工厂、公共空间、自然地貌这些真实应用需要的环境里既不适应也不泛化。</p><p>论文要解决的问题是：提供一个足够多样、足够高效的开放世界仿真集合，让被室内约束掩盖的问题重新可见。这个问题重要，是因为仿真器的场景分布直接定义了研究者能看到什么问题。当所有环境都是平地、无遮挡、单智能体时，非结构地形的攀爬跳跃、跨形态迁移、感知控制闭环的延迟这三类困难根本不会出现在实验结果里，社区也就不会去解决它们。论文的实验给出了这一点的直接量化：人类玩家在 Roof 环境上成功率 1.00、平均 515 步，而在线 RL 智能体成功率 0.32、平均 1660 步，GPT-4o 成功率 0.00。这个差距在任何室内导航 benchmark 上都看不到。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>TDW 与 LEGENT 基于 Unity 提供多模态平台，能做交互与物理，但场景与可控实体数量有限，在大型室外环境中性能下降。V-IRL 用 Google Maps 的街景图像模拟真实世界，视觉真实度天然满分，但由静态图像拼合而成，没有物理交互能力。Habitat 3.0 开始探索社交交互，但局限在室内场景与有限的智能体互动；HAZARD 处理火灾洪水这类动态场景，但只支持单智能体。</p><p>不够用的地方是精确的：这些工作要么场景多样但实体单一，要么实体丰富但场景受限，没有一个能同时提供大尺度多样场景加异构可控实体。为什么之前没做？可以推断有两重原因——一是高质量大尺度 3D 场景的制作成本极高，论文自己说这批资产是两年间从虚幻商城累计购买、花费超过一万美元；二是即便有了场景，原始 UnrealCV 是为计算机视觉合成数据设计的，帧率没有为实时交互优化，跑不动强化学习需要的海量试错。这两个瓶颈中，第一个是钱的问题，第二个是工程问题，论文两个都动手解决了。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是三个已有观察。第一，3D 场景与形态的多样性是空间智能的基础，智能体需要在复杂 3D 世界里主动感知、推理、规划、行动。第二，多智能体交互的复杂性是社会智能的基础，心智理论、协商、协作、竞争都需要有别的智能体在场。第三，仿真评测能在真机部署失败造成硬件损失之前暴露局限。</p><p>一个认真的研究者会先问：为什么现有仿真器不能满足这三条？答案是场景来源。学术界自建场景成本高、数量有限；扫描真实场景（Gibson、Matterport）只能得到静态几何，无法交互。但游戏资产市场上有大量艺术家精心制作的高质量场景，光照、纹理、动态效果都接近真实——这批资产一直存在，只是没人系统性地把它们接入具身 AI 的研究管线。</p><p>接下来是工程瓶颈。UnrealCV 提供了 Python 与虚幻引擎之间的桥梁，但它的设计目标是&quot;生成合成数据集&quot;，不是&quot;每秒交互几十次&quot;。定位到这一点后，优化方向就明确了：渲染端并行处理 object mask 与深度图，通信端引入批量命令协议减少往返，传输层用 IPC socket 替代 TCP socket 以在多环境高负载下保持稳定。</p><p>最后是接口设计。既然目标是让不懂虚幻引擎（C++ 与 Blueprint）的研究者也能用，那么就必须把场景打包成可执行二进制、把命令封装成 Python 函数、把任务定义放进 JSON 配置文件。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>仿真器的场景分布决定了社区能看见哪些问题。把 100 个艺术家制作的大尺度场景与 67 种可控形态放进同一套接口，再把交互帧率提上去让强化学习跑得动，那些在平坦室内被平均掉的困难——需要爬箱子跳障碍的非结构地形、换成机器狗后视角与运动能力都变了的形态迁移、人群中目标被遮挡时闭环延迟带来的跟丢——就会自己浮现出来。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以主动视觉跟踪任务为例走一遍。</p><ul><li><strong>场景</strong>：100 个基于 UE4/UE5 的场景，按内容分为室内、室外、内外兼有（46 个）；按尺度分为 indoor（15）、building（23）、community（28）、landscape（35），最大的 Medieval Nature Environment 超过 16 平方公里。还按空间结构（多层、拓扑、平坦、陡峭）与动态因素（天气、火、气体、流体、可交互物体）打标签，风格标签覆盖西方/亚洲/中东、中世纪/现代/科幻。</li><li><strong>可控实体</strong>：七类共 67 种——19 个人类、27 种动物、3 辆汽车、14 种四足机器人、3 辆摩托、1 架四旋翼，加上虚拟相机。每个实体带骨骼网格、局部运动系统与导航系统，可通过 API 改尺寸、外观、相机位置。每个实体自带第一人称相机，可取 RGB、深度、表面法线、实例分割。</li><li><strong>运动与导航</strong>：运动基于 Smart Locomotion 动画框架，交互是动画驱动而非物理驱动——开门是二值状态切换而不是真的操作门把手，蹲下跳跃攀爬是位置动画。导航基于 NavMesh，内置 AI 控制器可自主寻路避障；城市地图手工分割了人行道与车行道，行人优先走人行道、车辆优先走车道。</li><li><strong>UnrealCV+</strong>：渲染并行化、批量命令协议、IPC socket。表 6 给出六个场景的 FPS 提升，例如 FlexibleRoom（2440 平方米）的各项命令从原始 UnrealCV 的 74/70/109/52/35/13/8 提升到 85/164/137/100/94/40/27，最大的 16 平方公里场景也提升到 70/112/97/74/29/14/10。</li><li><strong>Gym 接口与工具箱</strong>：任务配置写进 JSON（场景名、动作空间、相机放置、重置区域、奖励函数），另有一套 gym wrapper——environment augmentation 做场景增广、population control 调整场景中智能体数量、time dilation 调整控制频率。还有一个 launch 工具支持在一台机器上按 GPU ID 启动多个环境，供分布式在线 RL 使用。</li></ul><p>跟踪任务的具体设定：人类角色作为 tracker，连续动作空间，角速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">30°/</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">30°/</span><span class="mord mathnormal">s</span><span class="mclose">]</span></span></span></span>、线速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mord mathnormal">m</span><span class="mord">/</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mord mathnormal">m</span><span class="mord">/</span><span class="mord mathnormal">s</span><span class="mclose">]</span></span></span></span>，episode 最长 500 步。离线数据用状态基专家策略加多级扰动策略自动生成，三个数据集（1 环境、2 环境、8 环境）总量都是 10 万步以保证公平，用 CQL 训练，网络沿用 Zhong 等人的 Mask Encoder 加 Temporal Encoder 加 Actor-Critic 结构。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化只在两个任务的奖励函数上。</p><p>导航的单步奖励同时鼓励靠近目标与朝向目标：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="mop">tanh</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">max</span><span class="mopen">(</span><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">300</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">90°</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">i</span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 时刻智能体与目标的欧氏距离，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">i</span><span class="mord">∣</span></span></span></span> 是当前朝向与目标方向的绝对角度误差。第一项用分母 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">max</span><span class="mopen">(</span><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">300</span><span class="mclose">)</span></span></span></span> 做归一化，直觉是让&quot;距离缩短的比例&quot;而非绝对量决定奖励——离得远时缩短 3 米和离得近时缩短 3 米的价值不同，而 300 这个下界防止距离很小时分母趋零导致奖励爆炸。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mop">tanh</span></span></span></span> 进一步把值域压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span>。第二项是朝向惩罚，按 90 度归一化。成功判据是距离小于 3 米且相对朝向误差小于 30 度，步数上限 2000。</p><p>跟踪的奖励在智能体自身坐标系下定义：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3074em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.263em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">ρ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span></span></span></span> 是目标相对 tracker 的极坐标，期望位置 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">2.5</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">m</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">)</span></span></span></span>，即目标应该在正前方 2.5 米处。误差按视场范围 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 归一化，所以完美跟踪时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，目标跑出视场时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 接近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">1</span></span></span></span>。这个形式的好处是把&quot;跟丢&quot;和&quot;跟得偏&quot;放在同一个连续尺度上，不需要额外的终止惩罚。</p><p>评测指标用 SPL：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.4162em;vertical-align:-0.52em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8962em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">a</span><span class="mtight">x</span></span><span class="mopen mtight">(</span><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mtight">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mclose mtight">)</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.4101em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mtight">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.52em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>，同时考虑成功与否与路径效率，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是最短路径长度、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是实际路径长度。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>非结构地形上现有方法差多少？</strong> Roof 环境有多层楼梯与散落管道，Factory 环境有紧凑箱体与狭窄通道，动作空间含前后移动、左右转、跳跃（连续两次跳跃触发攀爬）、蹲下、保持。结果（EL/SR/SPL）：Roof 上在线 RL 1660/0.32/0.10，GPT-4o 2000/0.00/0.00，人类 515/1.00/0.97；Industrial Area 上分别是 261/0.52/0.31、369/0.20/0.08、158/1.00/0.98。RL 智能体确实学会了爬箱子翻墙跳障碍走近路，但离人类还差得很远；GPT-4o 在复杂 3D 场景推理上几乎完全不行。人类基线用了五男五女共十位评测者，每人重复五次。</p><p><strong>环境多样性对泛化有多重要？</strong> 三个总量相同（10 万步）但来源环境数不同的离线数据集，在 16 个未见环境（分四类：室内、宫殿、荒野、现代城市）上测试。趋势清晰：环境数从 1 增到 8，四个类别的平均成功率普遍上升。荒野类提升最明显——SnowMap 从 0.62 到 0.86，RealLandscape 从 0.42 到 0.70；宫殿类 WesternGarden 从 0.54 到 0.82。只用抽象的 FlexibleRoom 训练的 1-Env 版本在所有类别上都最弱。</p><p><strong>人群干扰下哪些方法稳？</strong> 四个代表环境加 0/4/10 个随机走动的干扰者。RL（8 环境）的成功率是 0.76 / 0.68 / 0.56，衰减平缓。PID 因目标被遮挡时反应滞后而失败（0.34 / 0.30 / 0.14）。OpenVLA 近距离能跟但误差累积后失准，10 个干扰者时成功率归零。GPT-4o 与 OpenVLA 都极易被干扰者带偏，跟错目标。</p><p><strong>跨形态能迁移吗？</strong> 把在人类角色上训练的策略直接用到四足机器狗上。RL（8 环境）在 4 个干扰者下成功率从 0.68 掉到 0.48，10 个干扰者下从 0.56 掉到 0.40。视角高度与运动能力的变化带来的损失是实打实的。</p><p><strong>控制频率有多要紧？</strong> 用 time dilation wrapper 模拟不同控制频率，在 FlexibleRoom 上测 RL（1 环境）智能体：3 FPS 时 ER/EL/SR 为 184/377/0.34，10 FPS 为 303/449/0.62，30 FPS 为 368/482/0.92，不做频率控制为 275/425/0.74。低于 10 FPS 后性能显著下降。这个结果直接说明了为什么大模型智能体在动态场景里吃亏——GPT-4o 处理原始图像时的延迟本身就是失败原因之一。</p><p><strong>跨平台还成立吗？</strong> 把策略迁到 ThreeDWorld 的 Suburb Scene 上跟踪 Magnebot，1-Env 得 377/0.65，8-Envs 得 493/0.80。真机上用轮式机器人跟踪走 S 形路线的人，五次试验全部成功，改用平均偏移与 IoU 衡量：1-Env 为 764/328，8-Envs 为 833/393。多样性训练的收益跨过了仿真器边界，也跨到了真机。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：具身智能体的研究被室内仿真器的场景分布限制住了，非结构地形、跨形态迁移、闭环延迟这三类开放世界难题在平坦室内环境里根本不会暴露。UnrealZoo 用两年时间从虚幻商城累计购入 100 个艺术家制作的场景（最大 16 平方公里）与 67 种可控形态，并把 UnrealCV 的渲染与通信优化成 UnrealCV+，让强化学习需要的高频交互变得可行。导航实验显示人类成功率 1.00 而在线 RL 只有 0.32、GPT-4o 为 0.00。跟踪实验显示训练环境数从 1 增到 8 能在 16 个未见环境上普遍提升成功率，且收益能迁到 ThreeDWorld 与真机。控制频率实验显示低于 10 FPS 后性能显著下降，人类策略换到机器狗后成功率从 0.68 掉到 0.48。</p><p><strong>3 句话版</strong>：把 100 个大尺度实景场景与 67 种形态接入统一的 Gym 接口，并把交互帧率优化到能跑 RL。环境多样性对泛化的收益被定量证实并迁移到了真机。同时暴露了三个此前被掩盖的问题：非结构地形导航、跨形态迁移、感知控制闭环延迟。</p><p><strong>1 句话版</strong>：换一批更像真实世界的场景，具身智能体与人类的差距立刻从&quot;几个百分点&quot;变成&quot;0.32 对 1.00&quot;。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>视觉真实度是仿真到现实迁移的主要瓶颈，物理保真度可以牺牲</strong>。整套设计都建立在这个取舍上——交互是动画驱动而非物理驱动，开门是二值状态切换而不是操作门把手，蹲下跳跃攀爬是位置动画。论文在 limitation 里明确承认&quot;当前版本聚焦视觉渲染与交互，而非控制层面物理交互的精确性&quot;。</p><p>这在实践中相当危险。跳跃与攀爬恰恰是 Roof 与 Factory 环境的核心挑战，而它们是动画播放而非动力学求解。这意味着智能体学到的&quot;什么时候该跳&quot;是关于动画触发条件的知识，不是关于自身质量、速度、摩擦、可达高度的知识。真机上的跳跃受关节力矩与落地稳定性约束，动画里的跳跃只受触发条件约束——两者的决策边界很可能完全不同。同理，机器狗在 UnrealZoo 里的运动是四足动画，与真实四足控制器的步态、加速度限制、地形适应能力没有对应关系，所以&quot;跨形态迁移成功率从 0.68 掉到 0.48&quot;这个数字测的可能主要是视角高度变化的影响，而非真实形态差异的影响。</p><p>论文提供的正面证据是真机验证：轮式机器人跟踪 S 形路线五次全成功，8-Envs 优于 1-Env。但这个证据的说服力有限——跟踪任务的动作空间只有角速度与线速度两维，是所有具身任务里对物理保真度要求最低的一类，轮式底盘的运动学也最接近仿真里的简单平移旋转。缺失的关键证据是：涉及跳跃、攀爬、蹲行的导航策略是否也能迁到真机（比如真实四足机器人）。论文只在跟踪任务上做了真机验证，导航任务完全没有。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要买场景：</p><ul><li><strong>数据</strong>：UnrealZoo 已发布可执行二进制，直接下载其中的 FlexibleRoom 与两三个真实场景。</li><li><strong>实现</strong>：不必复现 RL 训练。先做 UnrealCV+ 的 FPS 基准——按论文方法对每个 API 函数调用 1000 次记录耗时，分别在原始 UnrealCV 与 UnrealCV+ 下测量，覆盖单图渲染、mask 渲染、深度渲染、多智能体批量交互，图像分辨率固定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">640</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">480</span></span></span></span>。</li><li><strong>核心实验</strong>：用 time dilation wrapper 复现控制频率消融。拿论文提供的预训练跟踪策略（或自己用 CQL 在单环境 10 万步上训一个，论文说 4090 上两小时接近收敛），在 3/10/30 FPS 三档下各跑 50 个 episode。</li><li><strong>判据</strong>：如果 FPS 提升幅度与论文表 6 一致，说明工程贡献可复现。如果控制频率从 30 降到 3 时成功率的下降幅度接近 0.92 到 0.34，则复现了&quot;闭环延迟是开放世界的关键约束&quot;这一核心结论。若成功率对频率不敏感，说明该结论依赖于特定的策略或环境，泛化性存疑。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出一个<strong>替代解释</strong>：多样性带来的收益可能主要是<strong>视觉表观的域随机化效果</strong>，与&quot;开放世界的空间复杂度&quot;无关。注意跟踪策略的输入是 Mask Encoder 处理的分割掩码，而非 RGB 图像——如果输入已经是掩码，那么八个环境提供的额外信息就不是&quot;更多样的纹理光照&quot;，而是&quot;更多样的目标运动模式与遮挡模式&quot;。但论文的 1-Env 基线用的是 FlexibleRoom，一个&quot;物体呈现为带随机图案的几何形状&quot;的抽象环境，它的目标运动模式本来就单调。</p><p>设计的反例实验：构造一个<strong>运动模式匹配</strong>的对照——在单个真实场景里，用与八环境数据集相同的多级扰动强度、相同的目标轨迹分布，采集 10 万步数据训练。如果这个&quot;单环境但运动多样&quot;的策略追平 8-Envs，那么&quot;环境多样性&quot;这个说法就该改成&quot;行为多样性&quot;，论文的核心 claim 需要重新表述。论文的三个数据集在环境数上有差异，但在目标行为分布上是否受控，文中没有说明。</p><p>第二类可预测失效：论文自己在 limitation 里承认因商城内容许可限制无法开源完整环境源码，只能发布可执行二进制。这意味着社区无法修改场景、无法添加新的交互对象、无法验证场景内部的实现细节。一个 benchmark 如果不可审计不可修改，它在多大程度上能承担&quot;标准测试床&quot;的角色是存疑的。可以预测的后果是：当研究者需要一个论文没有预设的任务（比如物体操作、工具使用、环境改造），他们只能等作者扩展 UnrealCV 命令系统，而不能自己动手——这与论文宣称的&quot;确保 UnrealZoo 随具身智能体演化而保持适应性&quot;存在张力。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：控制频率实验给出了一个被论文点到但没有深挖的发现——30 FPS 下成功率 0.92，而&quot;不做频率控制&quot;（即让策略以自己的推理速度运行）只有 0.74，比 30 FPS 差但比 10 FPS 好。这暗示真实部署时智能体面对的不是一个固定的控制频率，而是一个由自身推理开销决定的<strong>可变频率</strong>，并且这个频率与决策质量之间存在权衡：更大的模型推理更慢，但每一步决策更好。论文把这个现象当成&quot;需要更高效的模型&quot;的证据，但它其实指向一个更根本的问题——当前所有具身策略的评测都默认控制频率是环境给定的外生常量。</p><p><strong>新 framing</strong>：把推理延迟作为<strong>策略自身的决策变量</strong>而非外生参数。具体做法是让智能体在每一步显式选择&quot;用多少计算预算做这次决策&quot;——可以快速反应（浅层网络、上一步动作外推），也可以慢速深思（完整前向、多步规划），代价是环境在思考期间继续演化。这不是&quot;加速推理&quot;，而是把&quot;何时该快、何时该慢&quot;变成需要学习的策略维度。UnrealZoo 的 time dilation wrapper 恰好提供了实现这个框架所需的基础设施——它已经能把仿真时间与真实时间解耦。</p><p><strong>可借鉴的相邻领域工具</strong>：实时系统里的 anytime algorithm 与 imprecise computation 形式化了&quot;计算时间与结果质量的权衡&quot;；认知科学里的双系统理论（快思考与慢思考）提供了行为层面的组织原则；LLM 领域近期的自适应推理长度（按问题难度决定思考 token 数）提供了可直接借鉴的训练目标形式。</p><p><strong>第一个实验</strong>：在 UnrealZoo 的社交跟踪场景（4 个干扰者）上，训练一个带两档推理模式的策略——快档只跑 Mask Encoder 加一个线性头，慢档跑完整的 Temporal Encoder 加 Actor-Critic，两档的实际耗时通过 time dilation 映射成不同的环境步进量。奖励沿用原跟踪奖励，不加任何关于&quot;该用哪档&quot;的显式监督。测量三件事：一是与固定档位基线相比的成功率；二是慢档被触发的时刻分布（预期集中在目标即将被遮挡或转向的时刻）；三是平均每步计算量。如果自适应策略在计算量低于纯慢档的同时成功率不低于纯慢档，就证明&quot;延迟应该是内生决策&quot;这一 framing 有价值。</p>',56)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
